// Typed client for the Kork (code name zelda) JSON API. See docs/api.md for the contract.

export interface User {
  id: string;
  email: string;
  email_verified: boolean;
  is_admin: boolean;
  created_at: string;
}

export type ServiceInput = "handle" | "url" | "text" | "email" | "phone";

export interface CatalogService {
  key: string;
  name: string;
  category: string;
  input: ServiceInput;
  placeholder: string;
  prefix: string;
  copy_only: boolean;
  /** Trusted inline SVG markup generated by the server. */
  icon_svg?: string;
}

export interface KeyName {
  key: string;
  name: string;
}

export interface BlockTypeInfo extends KeyName {
  description: string;
}

export interface ThemeColors {
  bg: string;
  surface: string;
  text: string;
  muted: string;
  accent: string;
  button_bg: string;
  button_text: string;
}

export const COLOR_KEYS: ReadonlyArray<keyof ThemeColors> = [
  "bg",
  "surface",
  "text",
  "muted",
  "accent",
  "button_bg",
  "button_text",
];

export interface CatalogTheme {
  key: string;
  name: string;
  colors: ThemeColors;
  font: string;
  button_style: string;
  button_shape: string;
  layout: string;
  background: ThemeBackground;
}

export interface CatalogFeatures {
  custom_domains: boolean;
}

export interface Catalog {
  services: CatalogService[];
  /** Missing on older servers; treat absent flags as enabled. */
  features?: CatalogFeatures;
  categories: KeyName[];
  block_types: BlockTypeInfo[];
  themes: CatalogTheme[];
  fonts: KeyName[];
  button_styles: KeyName[];
  button_shapes: KeyName[];
  layouts: KeyName[];
  embed_providers: string[];
}

export type BackgroundKind = "solid" | "gradient" | "image";

export interface ThemeBackground {
  kind: BackgroundKind;
  color2?: string;
  image_upload_id?: string;
}

export interface Theme {
  preset: string;
  colors: ThemeColors;
  font: string;
  button_style: string;
  button_shape: string;
  layout: string;
  background: ThemeBackground;
}

export interface ThemePatch {
  preset?: string;
  colors?: Partial<ThemeColors>;
  font?: string;
  button_style?: string;
  button_shape?: string;
  layout?: string;
  background?: Partial<ThemeBackground>;
}

export type BlockType =
  | "link"
  | "service"
  | "heading"
  | "text"
  | "divider"
  | "image"
  | "embed"
  | "qr"
  | "copy"
  | "contact"
  | "map";

/** Block data is a flat object of string/boolean values keyed per block type. */
export type BlockData = Record<string, string | boolean | undefined>;

export interface Block {
  id: string;
  type: BlockType;
  data: BlockData;
  enabled: boolean;
  position: number;
  label: string;
}

export interface Domain {
  id: string;
  hostname: string;
  verified: boolean;
  txt_name: string;
  txt_value: string;
  target: string;
  created_at: string;
}

export interface PageSummary {
  id: string;
  slug: string;
  title: string;
  published: boolean;
  url: string;
  updated_at: string;
}

export interface Page {
  id: string;
  slug: string;
  title: string;
  bio: string;
  avatar_url: string | null;
  avatar_upload_id: string | null;
  published: boolean;
  suspended: boolean;
  url: string;
  theme: Theme;
  blocks: Block[];
  domains: Domain[];
  created_at: string;
  updated_at: string;
}

export interface PagePatch {
  slug?: string;
  title?: string;
  bio?: string;
  avatar_upload_id?: string | null;
  theme?: ThemePatch;
  published?: boolean;
}

export interface SlugCheck {
  available: boolean;
  reason?: string;
}

export interface NameCount {
  name: string;
  count: number;
}

export interface Stats {
  /** The range actually returned; the server caps it (30 days for now). */
  days?: number;
  total_views: number;
  views: { day: string; count: number }[];
  /** `ctr` is clicks divided by page views over the range. */
  blocks: { block_id: string; label: string; count: number; ctr?: number }[];
  /** Top 20 referrer domains; "direct" and "other" are special rows. */
  referrers?: NameCount[];
  /** Top 20 ISO country codes, or "unknown". */
  countries?: NameCount[];
}

export interface AccountSettings {
  weekly_stats_email: boolean;
}

export interface Upload {
  id: string;
  url: string;
  content_type: string;
  size: number;
}

export type ReportReason = "spam" | "scam" | "impersonation" | "illegal" | "other";

export interface Report {
  id: string;
  page_id: string;
  slug: string;
  reason: ReportReason;
  details: string;
  created_at: string;
  resolved: boolean;
}

export class ApiError extends Error {
  readonly status: number;
  readonly code: string;
  readonly field?: string;

  constructor(status: number, code: string, message: string, field?: string) {
    super(message);
    this.name = "ApiError";
    this.status = status;
    this.code = code;
    this.field = field;
  }
}

/**
 * Turn a non-2xx response body into an ApiError. Tolerates empty, non-JSON,
 * or malformed bodies so callers always get a readable message.
 */
export function parseApiError(status: number, bodyText: string): ApiError {
  let code = `http_${status}`;
  let message = defaultMessage(status);
  let field: string | undefined;
  if (bodyText) {
    try {
      const parsed: unknown = JSON.parse(bodyText);
      if (parsed && typeof parsed === "object" && "error" in parsed) {
        const err = (parsed as { error: unknown }).error;
        if (err && typeof err === "object") {
          const e = err as Record<string, unknown>;
          if (typeof e.code === "string" && e.code) code = e.code;
          if (typeof e.message === "string" && e.message) message = e.message;
          if (typeof e.field === "string" && e.field) field = e.field;
        }
      }
    } catch {
      // Not JSON; keep the default message.
    }
  }
  return new ApiError(status, code, message, field);
}

function defaultMessage(status: number): string {
  if (status === 401) return "Please sign in to continue.";
  if (status === 403) return "You don't have permission to do that.";
  if (status === 404) return "Not found.";
  if (status === 413) return "That file is too large.";
  if (status === 429) return "Too many requests. Please wait a moment and try again.";
  if (status >= 500) return "Something went wrong on our side. Please try again.";
  return "Request failed.";
}

export function errorMessage(err: unknown): string {
  if (err instanceof ApiError) return err.message;
  if (err instanceof Error) return err.message;
  return "Something went wrong.";
}

type Method = "GET" | "POST" | "PATCH" | "PUT" | "DELETE";

async function request<T>(method: Method, path: string, body?: unknown): Promise<T> {
  const headers: Record<string, string> = {
    "X-Requested-With": "zelda",
    Accept: "application/json",
  };
  let payload: BodyInit | undefined;
  if (body instanceof FormData) {
    payload = body;
  } else if (body !== undefined) {
    headers["Content-Type"] = "application/json";
    payload = JSON.stringify(body);
  }
  let res: Response;
  try {
    res = await fetch(path, { method, headers, body: payload, credentials: "same-origin" });
  } catch {
    throw new ApiError(0, "network", "Can't reach the server. Check your connection.");
  }
  const text = await res.text();
  if (!res.ok) throw parseApiError(res.status, text);
  if (!text) return undefined as T;
  try {
    return JSON.parse(text) as T;
  } catch {
    throw new ApiError(res.status, "bad_response", "The server sent an unexpected response.");
  }
}

const enc = encodeURIComponent;

/**
 * Auth endpoints are documented as returning `{user}`. Accept both the wrapped
 * form and a bare User object so a small backend difference doesn't break login.
 */
export function unwrapUser(body: unknown): User {
  if (body && typeof body === "object" && "user" in body) {
    const inner = (body as { user: unknown }).user;
    if (inner && typeof inner === "object") return inner as User;
  }
  return body as User;
}

export const api = {
  // Auth
  me: () => request<unknown>("GET", "/api/auth/me").then(unwrapUser),
  signup: (email: string, password: string) =>
    request<unknown>("POST", "/api/auth/signup", { email, password }).then(unwrapUser),
  login: (email: string, password: string) =>
    request<unknown>("POST", "/api/auth/login", { email, password }).then(unwrapUser),
  logout: () => request<void>("POST", "/api/auth/logout"),
  verify: (token: string) =>
    request<unknown>("POST", "/api/auth/verify", { token }).then(unwrapUser),
  resendVerification: () => request<void>("POST", "/api/auth/resend-verification"),
  forgot: (email: string) => request<void>("POST", "/api/auth/forgot", { email }),
  reset: (token: string, password: string) =>
    request<void>("POST", "/api/auth/reset", { token, password }),

  // Catalog
  catalog: () => request<Catalog>("GET", "/api/catalog"),

  // Pages
  listPages: () => request<PageSummary[]>("GET", "/api/pages"),
  createPage: (slug: string, title: string) =>
    request<Page>("POST", "/api/pages", { slug, title }),
  getPage: (id: string) => request<Page>("GET", `/api/pages/${enc(id)}`),
  updatePage: (id: string, patch: PagePatch) =>
    request<Page>("PATCH", `/api/pages/${enc(id)}`, patch),
  deletePage: (id: string) => request<void>("DELETE", `/api/pages/${enc(id)}`),
  checkSlug: (slug: string) => request<SlugCheck>("GET", `/api/slugs/${enc(slug)}`),
  stats: (id: string, days = 30) =>
    request<Stats>("GET", `/api/pages/${enc(id)}/stats?days=${days}`),
  qrUrl: (id: string) => `/api/pages/${enc(id)}/qr.svg`,

  // Account
  accountSettings: () => request<AccountSettings>("GET", "/api/account/settings"),
  updateAccountSettings: (patch: Partial<AccountSettings>) =>
    request<AccountSettings>("PATCH", "/api/account/settings", patch),

  // Blocks
  createBlock: (pageId: string, type: BlockType, data: BlockData, enabled = true) =>
    request<Block>("POST", `/api/pages/${enc(pageId)}/blocks`, { type, data, enabled }),
  updateBlock: (pageId: string, blockId: string, patch: { data?: BlockData; enabled?: boolean }) =>
    request<Block>("PATCH", `/api/pages/${enc(pageId)}/blocks/${enc(blockId)}`, patch),
  deleteBlock: (pageId: string, blockId: string) =>
    request<void>("DELETE", `/api/pages/${enc(pageId)}/blocks/${enc(blockId)}`),
  reorderBlocks: (pageId: string, ids: string[]) =>
    request<void>("PUT", `/api/pages/${enc(pageId)}/blocks/order`, { ids }),

  // Domains
  addDomain: (pageId: string, hostname: string) =>
    request<Domain>("POST", `/api/pages/${enc(pageId)}/domains`, { hostname }),
  verifyDomain: (pageId: string, domainId: string) =>
    request<Domain>("POST", `/api/pages/${enc(pageId)}/domains/${enc(domainId)}/verify`),
  deleteDomain: (pageId: string, domainId: string) =>
    request<void>("DELETE", `/api/pages/${enc(pageId)}/domains/${enc(domainId)}`),

  // Uploads
  upload: (file: File) => {
    const form = new FormData();
    form.append("file", file);
    return request<Upload>("POST", "/api/uploads", form);
  },

  // Admin
  reports: () => request<Report[]>("GET", "/api/admin/reports"),
  resolveReport: (id: string) => request<void>("POST", `/api/admin/reports/${enc(id)}/resolve`),
  suspendPage: (id: string, suspended: boolean) =>
    request<void>("POST", `/api/admin/pages/${enc(id)}/suspend`, { suspended }),
};
